.big{font-size:clamp(4rem,14vw,11rem)}
.facts{grid-template-columns:repeat(4,1fr)}
dt{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em;font-weight:600}
dd{font-family:"Archivo Black",Arial,sans-serif;font-size:1.15rem;margin-top:.3rem}
.story{grid-template-columns:2fr 1fr 1fr}
.story .wide{grid-row:span 2}
.cta{grid-template-columns:.5fr 3fr .3fr}
.cta a{display:inline-block;margin-top:1rem;background:var(--black);color:var(--white);padding:.9rem 1.4rem;font-weight:600;text-decoration:none;border:0}
.cta a:hover,.cta a:focus-visible{background:var(--red);outline:4px solid var(--yellow)}
.mini{display:grid;grid-template-columns:3fr 1fr;grid-template-rows:3fr 1fr;gap:6px;background:var(--black);border:6px solid var(--black);aspect-ratio:1;max-width:260px}
.mini i{background:var(--white)}.mini i:nth-child(2){background:var(--red)}.mini i:nth-child(3){background:var(--blue)}.mini i:nth-child(4){background:var(--yellow)}
.mini i:first-child{order:0}
footer{color:var(--grey);font-size:.8rem;padding:0 var(--line) var(--line)}
footer a{color:var(--yellow)}
@media (max-width:760px){.hero,.facts,.story,.cta{grid-template-columns:1fr}.hero .title,.hero .red{grid-column:auto;grid-row:auto}.story .wide{grid-row:auto}.cta .spacer{display:none}}
</style>
